# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 3: PHYSICAL APPEARANCE, BODY PARTS &amp; PERSONALITY</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Physical Appearance &amp; Body Parts</text>\n  <text x="40" y="98" font-size="12" fill="#1e3a8a">• What does he/she look like? (Dış görünüş)</text>\n  <text x="40" y="122" font-size="12" fill="#1e3a8a">• Height &amp; Build: tall, short, medium height, slim</text>\n  <text x="40" y="146" font-size="12" fill="#1e3a8a">• Hair &amp; Eyes: curly, wavy, straight hair;hazel eyes</text>\n  <text x="40" y="170" font-size="12" fill="#1e3a8a">• Body Parts: leg, knee, ankle, back, heart, stomach</text>\n  <text x="40" y="194" font-size="12" fill="#1e3a8a">• Items: necklace, bracelet, wallet, purse, trainers</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#2563eb">She has got long wavy hair and a lovely necklace.</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Personality &amp; Character Traits</text>\n  <text x="380" y="98" font-size="12" fill="#14532d">• What is he/she like? (Kişilik ve karakter)</text>\n  <text x="380" y="122" font-size="12" fill="#14532d">• Positive: polite, caring, patient, helpful, tidy</text>\n  <text x="380" y="146" font-size="12" fill="#14532d">• Intellectual: brilliant, clever, focused, organised</text>\n  <text x="380" y="170" font-size="12" fill="#14532d">• Social: social, independent, serious, simple</text>\n  <text x="380" y="194" font-size="12" fill="#14532d">• Negative: rude (kaba), lazy (tembel)</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">He is polite, patient and very helpful to his friends.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">COMPARING PEOPLE: COMPARATIVE &amp; SUPERLATIVE ADJECTIVES</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Short Adjectives (-er / the -est)</text>\n  <text x="35" y="100" font-size="11.5" fill="#713f12">• tall ➔ taller than / the tallest</text>\n  <text x="35" y="124" font-size="11.5" fill="#713f12">• short ➔ shorter / the shortest</text>\n  <text x="35" y="148" font-size="11.5" fill="#713f12">• slim ➔ slimmer / the slimmest</text>\n  <text x="35" y="172" font-size="11.5" fill="#713f12">• tidy ➔ tidier / the tidiest</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Ali is taller than Mert.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">Long Adjectives (more / the most)</text>\n  <text x="260" y="100" font-size="11.5" fill="#831843">• patient ➔ more patient than</text>\n  <text x="260" y="124" font-size="11.5" fill="#831843">• polite ➔ more polite than</text>\n  <text x="260" y="148" font-size="11.5" fill="#831843">• organised ➔ the most organised</text>\n  <text x="260" y="172" font-size="11.5" fill="#831843">• attractive ➔ the most attractive</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Ece is the most patient student.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">Irregular Adjectives (Düzensiz)</text>\n  <text x="485" y="100" font-size="11.5" fill="#581c87">• good ➔ better ➔ the best</text>\n  <text x="485" y="124" font-size="11.5" fill="#581c87">• bad ➔ worse ➔ the worst</text>\n  <text x="485" y="148" font-size="11.5" fill="#581c87">• far ➔ further ➔ the furthest</text>\n  <text x="485" y="172" font-size="11.5" fill="#581c87">• many/much ➔ more ➔ the most</text>\n  <text x="575" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Can is my best friend.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">POSSESSION (WHOSE / HAVE GOT), HABITS &amp; SOCIAL EXPRESSIONS</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Possession &amp; Daily Habits</text>\n  <text x="40" y="100" font-size="11.5" fill="#155e75">• Whose wallet is this? ➔ It is Kerem\'s wallet.</text>\n  <text x="40" y="124" font-size="11.5" fill="#155e75">• Whose trainers are these? ➔ They are mine.</text>\n  <text x="40" y="148" font-size="11.5" fill="#155e75">• Habit (Simple Present): She usually wears trainers.</text>\n  <text x="40" y="172" font-size="11.5" fill="#155e75">• Now (Present Continuous): She is wearing boots now.</text>\n  <text x="182" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">He always keeps his room tidy because he is organised.</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Target Social Language in Use</text>\n  <text x="375" y="102" font-size="11.5" font-weight="bold" fill="#9a3412">1. «You\'re full of beans this morning!»</text>\n  <text x="375" y="122" font-size="11" fill="#9a3412">(Bu sabah kıpır kıpırsın / çok enerjiksin!)</text>\n  <text x="375" y="150" font-size="11.5" font-weight="bold" fill="#9a3412">2. «Don\'t panic, just keep your cool!»</text>\n  <text x="375" y="170" font-size="11" fill="#9a3412">(Panik yapma, sakinliğini koru!)</text>\n  <text x="375" y="198" font-size="11.5" font-weight="bold" fill="#9a3412">3. «OK smarty pants, stop showing off!»</text>\n  <text x="375" y="218" font-size="11" fill="#9a3412">(Tamam çokbilmiş, hava atmayı bırak!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
